  1	#version 450
  2	
  3	#extension GL_KHR_cooperative_matrix : require
  4	#extension GL_KHR_memory_scope_semantics : require
  5	#extension GL_KHR_shader_subgroup_basic : require
  6	#extension GL_EXT_shader_16bit_storage : require
  7	#extension GL_EXT_shader_explicit_arithmetic_types_float16 : require
  8	#extension GL_EXT_control_flow_attributes : require
  9	
 10	// Causal grouped-query flash attention on the matrix cores, with the output
 11	// gate fused into its epilogue: the fourth of the full-attention layer's five
 12	// dispatches (LLM.md L2f).
 13	//
 14	// The flash structure is dit_attention_wmma.comp's and this file does not
 15	// re-litigate it — two cooperative-matrix GEMMs with an online softmax between
 16	// them, Q held in registers across the whole key loop, the row max taken from
 17	// a 16x16 fp32 staging tile because a cooperative matrix's element order is
 18	// not defined, the rescale applied as a row-constant matrix, and the softmax
 19	// denominator accumulated by appending a column of ones to V. It is a separate
 20	// shader rather than another arm of that one because it lives in this
 21	// vertical's binding contract (llm_common.glsl, which has a KV cache, an
 22	// indexer and a gate where the DiT's has none of them), and because of the two
 23	// things below.
 24	//
 25	// **The head dim is 256, not 128.** HDT doubles to 16, which doubles the query
 26	// fragments held in registers and the output accumulators with them: at QT=1
 27	// that is 16 A-fragments and 16 accumulators live across the key loop, and it
 28	// is why the ladder here starts at QT=1 rather than at the DiT's QT=2. The
 29	// arithmetic intensity argument is unchanged and was inert there anyway — what
 30	// decides this ladder is the register file.
 31	//
 32	// **The gate is fused into the store.** `attn_q` is [2560, 12288]: each head's
 33	// 256 query dims are immediately followed by 256 *gate* dims, and the gate is
 34	// a sigmoid applied to the attention **output**, not to the query. llama.cpp
 35	// spends a SIGMOID, a MUL and a CONT on it; here the epilogue already has the
 36	// output tile in LDS for the 1/rowSum divide, so the gate costs one extra read
 37	// of the fused projection's own fp32 row and the context leaves as fp16
 38	// straight into the output projection's A layout. Three of llama.cpp's lines
 39	// and a [T, 6144] round trip through DRAM, deleted.
 40	//
 41	// **The selection is a second mask, and a skip** (P7). `llm_attn_select.comp`
 42	// writes one bit per cache cell per token, and this kernel reads it exactly
 43	// where it reads the causal one: out of the block row max, so an unselected
 44	// cell cannot set the scale, and out of P, which is what removes it from both
 45	// O and the row sum. That much is what the reference does — `build_attn_qsa`
 46	// turns `top_k` back into an f16 mask and runs **dense** flash attention over
 47	// every cell — and on its own it is semantics and not a saving.
 48	//
 49	// So the mask is also read *before* the key block is, and a block with no
 50	// selected cell in any row is skipped whole. The two are the same answer: an
 51	// unselected cell contributes nothing to O and nothing to the row sum, so a
 52	// block of them contributes nothing, and the skip is bit-identical rather
 53	// than an approximation. What it changes is the **cost**, which is the reason
 54	// QSA exists: a decode step names 2051 cells however deep the cache is, they
 55	// fall in ~513 blocks of `ratio`, and at 64k of context four key blocks in
 56	// five hold none of them. At prefill it is close to inert — at ~50% density a
 57	// 32-cell block is eight indexer blocks and the chance all eight miss is
 58	// ~0.4% (L4b-3) — which is why this is a decode optimisation and only that.
 59	//
 60	// `selOff == NO_W` is the dense path, and it is the honest one below 2051
 61	// cells: at any prompt shorter than `top_k + ratio - 1` the selection names
 62	// every cell (research/l2e-attention.md), so running it would be the identity
 63	// and the branch is not an approximation.
 64	//
 65	// **The key range is split across workgroups at decode** (P8, `-DSPLITK`).
 66	//
 67	// The grid is (query blocks, heads), so a decode step — one token — dispatches
 68	// one workgroup a head: 24 of them, each a *single wave*, and each walking
 69	// every key block of the cache in turn. They all fit on the device at once,
 70	// so the dispatch's wall clock is **one wave's serial walk** and nothing
 71	// else: cutting the grid from 24 workgroups to 2 was measured at 1.00x, which
 72	// is what says the cost is neither the traffic nor the occupancy across heads
 73	// but the length of that walk. Adding heads cannot shorten it; only cutting
 74	// the walk can.
 75	//
 76	// So this build slices the key axis `pc.injOff` ways (ATTN_SPLITS) and gives
 77	// each slice its own workgroup — the grid's x becomes (query block, slice) —
 78	// and each writes its slice's **unnormalised** context beside the two numbers
 79	// an online softmax needs to be resumed: the slice's row max and its row sum.
 80	// `llm_attn_combine.comp` puts them back together. That is flash-decoding's
 81	// split, and it is exact in the same sense the block loop already is: the
 82	// same partial-softmax identity that lets the loop rescale by exp2(mo - mn)
 83	// when it meets a bigger max is what lets the combine rescale by
 84	// exp2(m_s - m*) when it meets the largest of the slices'.
 85	//
 86	// It is **not bit-identical** to the unsplit kernel and cannot be: the
 87	// rescales happen in a different order and fp32 addition is not associative.
 88	// What it is is the same arithmetic, gated on agreement with the reference
 89	// rather than with the other kernel — see TestAttnGPUSplitMatchesDense.
 90	//
 91	// **The query is a batch, the key and the value are a cache** (L7a). Row i of
 92	// query block q0 is cell `SEQ_PAST + q0 + i` and the keys run over every cell
 93	// the cache holds, `SEQ_PAST + tokens` of them, so the two operands no longer
 94	// share a plane geometry: the query's is `plane` padded token rows, the key's
 95	// and the value's are nKV cells. Every causal comparison is between a cell and
 96	// a *position*, and on a fresh sequence SEQ_PAST is zero and all of it is
 97	// what L2f measured.
 98	
 99	#include "llm_common.glsl"
100	
101	#ifndef QT
102	#define QT 1        // query tiles per wave
103	#endif
104	#ifndef KTIL
105	#define KTIL 4      // key tiles per block
106	#endif
107	#ifndef WAVE
108	#define WAVE 64
109	#endif
110	#ifndef HEAD_DIM
111	#define HEAD_DIM 256
112	#endif
113	
114	#define TILE 16
115	#define HDT (HEAD_DIM / TILE)
116	#define BM (QT * TILE)
117	#define BN (KTIL * TILE)
118	
119	layout(local_size_x = WAVE) in;
120	
121	#define ACC  coopmat<float, gl_ScopeSubgroup, TILE, TILE, gl_MatrixUseAccumulator>
122	#define ACCH coopmat<float16_t, gl_ScopeSubgroup, TILE, TILE, gl_MatrixUseAccumulator>
123	#define FRAG_A coopmat<float16_t, gl_ScopeSubgroup, TILE, TILE, gl_MatrixUseA>
124	#define FRAG_B coopmat<float16_t, gl_ScopeSubgroup, TILE, TILE, gl_MatrixUseB>
125	
126	shared float stage[QT * TILE * TILE];
127	shared float16_t pbuf[BM * BN];
128	shared float bcorr[QT * TILE * TILE];
129	shared float rowMax[BM];
130	shared float blkMax[BM];
131	shared float rowSum[BM];
132	// This key block's slice of the QSA bitmask, one word per (row, 32 cells).
133	// It is staged once a block rather than bit-tested out of the arena per
134	// element: the mask loop below touches BM*BN elements and the row max another
135	// BM*TILE, which is 512 global reads a block where the block's whole mask is
136	// BM*BN/32 words. Reading it per element cost the kernel 1.90x.
137	shared uint selw[BM * (BN / 32)];
138	// Whether any row of this key block has any cell selected at all.
139	shared uint blkAny;
140	
141	// stageSel loads this key block's slice of the QSA bitmask into LDS: one word
142	// per (row, 32 cells), read by both the row max and the mask loop below, and
143	// returns the OR of the words this lane staged — which is how the skip below
144	// learns whether the block has anything in it at all.
145	//
146	// `base` is a multiple of BN and BN a multiple of 32, so a word of the staged
147	// slice is a word of the arena and not a shift of one. A pad row has no
148	// selection — llm_attn_select.comp does not run past the prompt — so it stages
149	// as **zero**: nothing of it is visible, its softmax denominator is zero, and
150	// the epilogue turns that into a zero row rather than a NaN. (It used to stage
151	// all-ones and take the dense path for exactly that denominator; the skip
152	// below would then have been defeated by fifteen pad rows on every decode
153	// step, which is the one shape where the skip is worth anything.)
154	uint stageSel(uint lane, uint q0, uint base) {
155	    uint words = (pc.nKV + 31u) / 32u;
156	    uint acc = 0u;
157	    for (uint i = lane; i < BM * (BN / 32u); i += WAVE) {
158	        uint row = i / (BN / 32u), wd = i % (BN / 32u);
159	        uint token = q0 + row;
160	        uint w = (token >= pc.tokens) ? 0u
161	                                      : actu[pc.selOff + token * words + ((base + wd * 32u) >> 5u)];
162	        selw[i] = w;
163	        acc |= w;
164	    }
165	    return acc;
166	}
167	
168	// selected reads one bit out of the staged slice.
169	bool selected(uint row, uint col) {
170	    return (selw[row * (BN / 32u) + (col >> 5u)] & (1u << (col & 31u))) != 0u;
171	}
172	
173	void main() {
174	    uint head = gl_WorkGroupID.y;
175	#ifdef SPLITK
176	    // The grid's x carries both: `splits` slices of every query block, so
177	    // that a build which is not split keeps exactly the grid it had.
178	    uint splits = max(pc.injOff, 1u);
179	    uint sp = gl_WorkGroupID.x % splits;
180	    uint q0 = (gl_WorkGroupID.x / splits) * BM;
181	#else
182	    uint q0 = gl_WorkGroupID.x * BM;
183	#endif
184	    uint past = SEQ_PAST;
185	    uint n = past + pc.tokens;       // cells in the cache, keys to attend over
186	    uint lane = gl_LocalInvocationID.x;
187	    if (q0 >= pc.tokens || head >= pc.heads) {
188	        return;
189	    }
190	    bool sparse = pc.selOff != NO_W;
191	
192	    uint qTiles = pc.plane / TILE;
193	    uint kvTiles = pc.nKV / TILE;
194	    uint plane = head * qTiles * (HDT * TILE * TILE);
195	    uint rep = max(pc.heads / max(pc.kvHeads, 1u), 1u);
196	    uint kvPlane = (head / rep) * kvTiles * (HDT * TILE * TILE);
197	    uint qBase = pc.qOff + plane + (q0 / TILE) * (HDT * TILE * TILE);
198	    uint kBase = pc.kOff + kvPlane;
199	    uint vBase = pc.vOff + kvPlane;
200	
201	    FRAG_A fragQ[QT][HDT];
202	    [[unroll]] for (uint qq = 0u; qq < QT; ++qq) {
203	        [[unroll]] for (uint kt = 0u; kt < HDT; ++kt) {
204	            coopMatLoad(fragQ[qq][kt], hact, qBase + (qq * HDT + kt) * (TILE * TILE),
205	                TILE, gl_CooperativeMatrixLayoutRowMajor);
206	        }
207	    }
208	
209	    ACC o[QT][HDT];
210	    ACC lsum[QT];
211	    [[unroll]] for (uint qq = 0u; qq < QT; ++qq) {
212	        [[unroll]] for (uint j = 0u; j < HDT; ++j) {
213	            o[qq][j] = ACC(0.0);
214	        }
215	        lsum[qq] = ACC(0.0);
216	    }
217	    for (uint i = lane; i < BM; i += WAVE) {
218	        rowMax[i] = -1.0 / 0.0;
219	    }
220	    barrier();
221	
222	    const FRAG_B ones = FRAG_B(float16_t(1.0));
223	
224	    // Nothing past this query block's last row can be attended to, so the key
225	    // blocks beyond it are never read. Its last row is cell `past + q0 + BM - 1`.
226	    uint last = min(n, past + q0 + BM);
227	#ifdef SPLITK
228	    // **Every `splits`-th block, not a contiguous run of them**, and that is
229	    // a correctness requirement rather than a preference.
230	    //
231	    // A slice has to be a set of *absolute* key blocks that does not depend
232	    // on how the prompt was chunked, because L7a's gate is that it does not:
233	    // token at cell `pos` must come back bit for bit whether it arrived alone
234	    // or seventh of seven. Cutting `[0, last)` into `splits` contiguous runs
235	    // fails that — `last` is `min(n, past + q0 + BM)` and both `n` and `q0`
236	    // are the batch's, so a seven-token chunk and a one-token chunk put the
237	    // boundaries in different places and fold the partial softmaxes in a
238	    // different order. A stride is immune: block b belongs to slice
239	    // `b % splits` however the run was cut.
240	    //
241	    // The blocks past a row's causal extent that the stride then walks cost
242	    // nothing and change nothing, for the same reason the unsplit loop can
243	    // walk them: blkMax stays -inf, the correction is exactly 1.0, and P is
244	    // zeroed, so the accumulators come out untouched. And the stride balances
245	    // the slices where a contiguous cut would not — the QSA selection is
246	    // clustered (P7), so contiguous runs would hand one slice most of the
247	    // live blocks and its neighbours none.
248	    //
249	    // A slice with no block at all — `sp >= ceil(last/BN)` — falls straight
250	    // through to the epilogue, which writes the combine's identity: a row max
251	    // of -inf and a row sum of zero.
252	    for (uint base = sp * BN; base < last; base += splits * BN) {
253	#else
254	    for (uint base = 0u; base < last; base += BN) {
255	#endif
256	        uint cnt = min(BN, n - base);
257	
258	        // **The selection, before the block is read rather than after** (P7).
259	        // QSA names `top_k + ratio - 1` cells however deep the context is —
260	        // 2051 of them — and every other cell is masked out of both the row
261	        // max and P below, so a key block with nothing selected in it
262	        // contributes exactly nothing: blkMax stays -inf, the correction is
263	        // 1, and every element of P is zeroed. Skipping it is therefore
264	        // bit-identical, and it is the whole point of a sparse attention:
265	        // without this the kernel walked all `n` cells at every depth and the
266	        // selection bought semantics and no time at all (L4b-3). At a decode
267	        // step the 2051 cells fall in ~513 blocks of `ratio`, so at 64k of
268	        // context roughly four key blocks in five hold none of them.
269	        //
270	        // The staging has to move up here for it — it is the test — and it is
271	        // work this block was going to do anyway.
272	        if (sparse) {
273	            if (lane == 0u) {
274	                blkAny = 0u;
275	            }
276	            barrier();
277	            if (stageSel(lane, q0, base) != 0u) {
278	                atomicOr(blkAny, 1u);
279	            }
280	            barrier();
281	            if (blkAny == 0u) {
282	                continue;
283	            }
284	        }
285	
286	        ACC s[QT][KTIL];
287	        [[unroll]] for (uint qq = 0u; qq < QT; ++qq) {
288	            [[unroll]] for (uint kk = 0u; kk < KTIL; ++kk) {
289	                s[qq][kk] = ACC(0.0);
290	            }
291	        }
292	        [[unroll]] for (uint kt = 0u; kt < HDT; ++kt) {
293	            FRAG_B fragK[KTIL];
294	            [[unroll]] for (uint kk = 0u; kk < KTIL; ++kk) {
295	                coopMatLoad(fragK[kk], hact, kBase + ((base / TILE + kk) * HDT + kt) * (TILE * TILE),
296	                    TILE, gl_CooperativeMatrixLayoutColumnMajor);
297	            }
298	            [[unroll]] for (uint qq = 0u; qq < QT; ++qq) {
299	                [[unroll]] for (uint kk = 0u; kk < KTIL; ++kk) {
300	                    s[qq][kk] = coopMatMulAdd(fragQ[qq][kt], fragK[kk], s[qq][kk]);
301	                }
302	            }
303	        }
304	
305	        // The row max of this block, with the causal mask applied to the *max*
306	        // and not only to P: a future key that set the scale would leave every
307	        // real key's exp2 underflowing once the gap passed ~24 in log2 units.
308	        for (uint i = lane; i < BM; i += WAVE) {
309	            blkMax[i] = -1.0 / 0.0;
310	        }
311	        barrier();
312	        [[unroll]] for (uint kk = 0u; kk < KTIL; ++kk) {
313	            [[unroll]] for (uint qq = 0u; qq < QT; ++qq) {
314	                coopMatStore(s[qq][kk], stage, qq * (TILE * TILE), TILE,
315	                    gl_CooperativeMatrixLayoutRowMajor);
316	            }
317	            barrier();
318	            for (uint i = lane; i < BM; i += WAVE) {
319	                uint qi = i / TILE, r = i % TILE;
320	                float mx = blkMax[i];
321	                for (uint c = 0u; c < TILE; ++c) {
322	                    uint cell = base + kk * TILE + c;
323	                    if (cell > past + q0 + i) {
324	                        break;      // and every c after it, the row is done
325	                    }
326	                    if (sparse && !selected(i, kk * TILE + c)) {
327	                        continue;   // unselected: it must not set the scale
328	                    }
329	                    mx = max(mx, stage[qi * (TILE * TILE) + r * TILE + c]);
330	                }
331	                blkMax[i] = mx;
332	            }
333	            barrier();
334	        }
335	
336	        for (uint i = lane; i < BM; i += WAVE) {
337	            uint qi = i / TILE, r = i % TILE;
338	            float mo = rowMax[i];
339	            float mn = max(mo, blkMax[i]);
340	            rowMax[i] = mn;
341	            // exp2(-inf - m) is 0, so there is no first-block case. The equal
342	            // test is for the selection: a key block with nothing selected in
343	            // it leaves both maxima at -inf, and exp2(-inf - -inf) is a NaN
344	            // that would poison the accumulators for the rest of the row.
345	            float corr = (mo == mn) ? 1.0 : exp2(mo - mn);
346	            for (uint c = 0u; c < TILE; ++c) {
347	                stage[qi * (TILE * TILE) + r * TILE + c] = mn;
348	                bcorr[qi * (TILE * TILE) + r * TILE + c] = corr;
349	            }
350	        }
351	        barrier();
352	
353	        [[unroll]] for (uint qq = 0u; qq < QT; ++qq) {
354	            ACC mrow, ccorr;
355	            coopMatLoad(mrow, stage, qq * (TILE * TILE), TILE, gl_CooperativeMatrixLayoutRowMajor);
356	            coopMatLoad(ccorr, bcorr, qq * (TILE * TILE), TILE, gl_CooperativeMatrixLayoutRowMajor);
357	            [[unroll]] for (uint kk = 0u; kk < KTIL; ++kk) {
358	                ACC p = s[qq][kk] - mrow;
359	                [[unroll]] for (uint e = 0u; e < p.length(); ++e) {
360	                    p[e] = exp2(p[e]);
361	                }
362	                coopMatStore(ACCH(p), pbuf, (qq * TILE) * BN + kk * TILE, BN,
363	                    gl_CooperativeMatrixLayoutRowMajor);
364	            }
365	            [[unroll]] for (uint j = 0u; j < HDT; ++j) {
366	                o[qq][j] = o[qq][j] * ccorr;
367	            }
368	            lsum[qq] = lsum[qq] * ccorr;
369	        }
370	        barrier();
371	
372	        // Mask the pad keys and the future ones out of P, which is what
373	        // removes them from both O and the row sums. Without a selection only
374	        // the diagonal block needs it — every earlier block is entirely in the
375	        // past of every row — but the selection drops cells anywhere, so with
376	        // it on every block passes through here.
377	        if (sparse || cnt < BN || base + BN > past + q0) {
378	            for (uint i = lane; i < BM * BN; i += WAVE) {
379	                uint col = i & (BN - 1u);
380	                uint row = i / BN;
381	                if (col >= cnt || base + col > past + q0 + row ||
382	                    (sparse && !selected(row, col))) {
383	                    pbuf[i] = float16_t(0.0);
384	                }
385	            }
386	            barrier();
387	        }
388	
389	        FRAG_A fragP[QT][KTIL];
390	        [[unroll]] for (uint qq = 0u; qq < QT; ++qq) {
391	            [[unroll]] for (uint kk = 0u; kk < KTIL; ++kk) {
392	                coopMatLoad(fragP[qq][kk], pbuf, (qq * TILE) * BN + kk * TILE, BN,
393	                    gl_CooperativeMatrixLayoutRowMajor);
394	            }
395	        }
396	        [[unroll]] for (uint j = 0u; j < HDT; ++j) {
397	            FRAG_B fragV[KTIL];
398	            [[unroll]] for (uint kk = 0u; kk < KTIL; ++kk) {
399	                coopMatLoad(fragV[kk], hact, vBase + ((base / TILE + kk) * HDT + j) * (TILE * TILE),
400	                    TILE, gl_CooperativeMatrixLayoutColumnMajor);
401	            }
402	            [[unroll]] for (uint qq = 0u; qq < QT; ++qq) {
403	                [[unroll]] for (uint kk = 0u; kk < KTIL; ++kk) {
404	                    o[qq][j] = coopMatMulAdd(fragP[qq][kk], fragV[kk], o[qq][j]);
405	                }
406	            }
407	        }
408	        [[unroll]] for (uint qq = 0u; qq < QT; ++qq) {
409	            [[unroll]] for (uint kk = 0u; kk < KTIL; ++kk) {
410	                lsum[qq] = coopMatMulAdd(fragP[qq][kk], ones, lsum[qq]);
411	            }
412	        }
413	        barrier();
414	    }
415	
416	#ifdef SPLITK
417	    // ---- The split epilogue: this slice's partial, and how to resume it.
418	    //
419	    // Nothing is normalised and nothing is gated here — `o` is still relative
420	    // to this slice's own row max and `lsum` is still this slice's own
421	    // denominator, because neither is the row's until every slice has been
422	    // seen. The combine does the divide and the gate, once, off the assembled
423	    // row. A slice that got no block writes -inf and zero, which is the
424	    // identity there.
425	    [[unroll]] for (uint qq = 0u; qq < QT; ++qq) {
426	        coopMatStore(lsum[qq], stage, qq * (TILE * TILE), TILE,
427	            gl_CooperativeMatrixLayoutRowMajor);
428	    }
429	    barrier();
430	    for (uint i = lane; i < BM; i += WAVE) {
431	        uint qi = i / TILE, r = i % TILE;
432	        rowSum[i] = stage[qi * (TILE * TILE) + r * TILE];
433	    }
434	    barrier();
435	
436	    // The partial arena, ATTN_SPLIT (llm_common.glsl): the contexts first,
437	    // [heads][splits][tokens][headDim], then the pair per row behind them.
438	    uint slice = (head * splits + sp) * pc.tokens;
439	    uint mlBase = pc.resOff + pc.heads * splits * pc.tokens * pc.headDim;
440	    for (uint i = lane; i < BM; i += WAVE) {
441	        uint token = q0 + i;
442	        if (token < pc.tokens) {
443	            uint at = mlBase + (slice + token) * 2u;
444	            act[at] = rowMax[i];
445	            act[at + 1u] = rowSum[i];
446	        }
447	    }
448	    barrier();
449	
450	    [[unroll]] for (uint j = 0u; j < HDT; ++j) {
451	        [[unroll]] for (uint qq = 0u; qq < QT; ++qq) {
452	            coopMatStore(o[qq][j], stage, qq * (TILE * TILE), TILE,
453	                gl_CooperativeMatrixLayoutRowMajor);
454	        }
455	        barrier();
456	        // Four lanes a row, four floats each, as the gated store below. The
457	        // pad rows are skipped rather than written: unlike the context arena
458	        // this one is read back by a kernel that knows how many rows are
459	        // real, so there is nothing for a pad row to keep clean.
460	        for (uint i = lane; i < BM * 4u; i += WAVE) {
461	            uint row = i / 4u, part = i % 4u;
462	            uint token = q0 + row;
463	            if (token >= pc.tokens) {
464	                continue;
465	            }
466	            uint qi = row / TILE, r = row % TILE;
