403	                [[unroll]] for (uint kk = 0u; kk < KTIL; ++kk) {
404	                    o[qq][j] = coopMatMulAdd(fragP[qq][kk], fragV[kk], o[qq][j]);
405	                }
406	            }
407	        }
408	        [[unroll]] for (uint qq = 0u; qq < QT; ++qq) {
409	            [[unroll]] for (uint kk = 0u; kk < KTIL; ++kk) {
410	                lsum[qq] = coopMatMulAdd(fragP[qq][kk], ones, lsum[qq]);
411	            }
412	        }
413	        barrier();
414	    }
415	
416	#ifdef SPLITK
417	    // ---- The split epilogue: this slice's partial, and how to resume it.
418	    //
419	    // Nothing is normalised and nothing is gated here — `o` is still relative
420	    // to this slice's own row max and `lsum` is still this slice's own
421	    // denominator, because neither is the row's until every slice has been
422	    // seen. The combine does the divide and the gate, once, off the assembled
423	    // row. A slice that got no block writes -inf and zero, which is the
424	    // identity there.
425	    [[unroll]] for (uint qq = 0u; qq < QT; ++qq) {
426	        coopMatStore(lsum[qq], stage, qq * (TILE * TILE), TILE,
427	            gl_CooperativeMatrixLayoutRowMajor);
428	    }
429	    barrier();
430	    for (uint i = lane; i < BM; i += WAVE) {
431	        uint qi = i / TILE, r = i % TILE;
432	        rowSum[i] = stage[qi * (TILE * TILE) + r * TILE];
433	    }
434	    barrier();
435	
436	    // The partial arena, ATTN_SPLIT (llm_common.glsl): the contexts first,
437	    // [heads][splits][tokens][headDim], then the pair per row behind them.
