441	        uint token = q0 + i;
442	        if (token < pc.tokens) {
443	            uint at = mlBase + (slice + token) * 2u;
444	            act[at] = rowMax[i];
445	            act[at + 1u] = rowSum[i];
446	        }
447	    }
448	    barrier();
449	
450	    [[unroll]] for (uint j = 0u; j < HDT; ++j) {
451	        [[unroll]] for (uint qq = 0u; qq < QT; ++qq) {
452	            coopMatStore(o[qq][j], stage, qq * (TILE * TILE), TILE,
453	                gl_CooperativeMatrixLayoutRowMajor);
454	        }
455	        barrier();
456	        // Four lanes a row, four floats each, as the gated store below. The
457	        // pad rows are skipped rather than written: unlike the context arena
458	        // this one is read back by a kernel that knows how many rows are
459	        // real, so there is nothing for a pad row to keep clean.
460	        for (uint i = lane; i < BM * 4u; i += WAVE) {
461	            uint row = i / 4u, part = i % 4u;
462	            uint token = q0 + row;
463	            if (token >= pc.tokens) {
464	                continue;
465	            }
466	            uint qi = row / TILE, r = row % TILE;
467	            uint src = qi * (TILE * TILE) + r * TILE + part * 4u;
468	            uint dst = pc.resOff + (slice + token) * pc.headDim + j * TILE + part * 4u;
469	            [[unroll]] for (uint c = 0u; c < 4u; ++c) {
470	                act[dst + c] = stage[src + c];
471	            }
472	        }
473	        barrier();
474	    }
475	}
476	#else
477	    // ---- Epilogue: the softmax divide and the output gate, together.
478	    //
479	    // Every column of lsum holds the row sum, so column 0 is read out of a
480	    // staging tile. The output goes through the same tile rather than being
481	    // stored as a matrix, because the gate is indexed by (row, column) and a
482	    // cooperative matrix's element order is not defined — which is the same
483	    // reason the row max needed a staging tile.
484	    [[unroll]] for (uint qq = 0u; qq < QT; ++qq) {
485	        coopMatStore(lsum[qq], stage, qq * (TILE * TILE), TILE,
486	            gl_CooperativeMatrixLayoutRowMajor);
487	    }
488	    barrier();
489	    for (uint i = lane; i < BM; i += WAVE) {
490	        uint qi = i / TILE, r = i % TILE;
491	        rowSum[i] = stage[qi * (TILE * TILE) + r * TILE];
492	    }
493	    barrier();
494	
495	    uint gateCol = pc.qkvOff + head * 2u * pc.headDim + pc.headDim;
496	    [[unroll]] for (uint j = 0u; j < HDT; ++j) {
497	        [[unroll]] for (uint qq = 0u; qq < QT; ++qq) {
498	            coopMatStore(o[qq][j], stage, qq * (TILE * TILE), TILE,
499	                gl_CooperativeMatrixLayoutRowMajor);
500	        }
501	        barrier();
502	        // Four lanes per row, four contiguous halves each. The rows past the
503	        // prompt are written too rather than branched around: they are the
504	        // output projection's pad rows, whose products nothing reads.
505	        for (uint i = lane; i < BM * 4u; i += WAVE) {
506	            uint row = i / 4u, part = i % 4u;
507	            uint token = q0 + row;
508	            uint qi = row / TILE, r = row % TILE;
509	            // A pad row sees nothing once the selection is on, and a row
510	            // that sees nothing has a zero denominator. Its products are
511	            // never read — it is the output projection's padding — but a NaN
512	            // there would be a NaN in an arena the next pass reuses, so it is
513	            // written as a zero row instead.
514	            float inv = (rowSum[row] > 0.0) ? 1.0 / rowSum[row] : 0.0;
