516	            uint d0 = j * TILE + part * 4u;
517	            uint dst = pc.ctxOff + token * pc.ldCtx + head * pc.headDim + d0;
518	            [[unroll]] for (uint c = 0u; c < 4u; ++c) {
519	                float g = act[gateCol + token * pc.gemmN + d0 + c];
520	                hact[dst + c] = float16_t(stage[src + c] * inv / (1.0 + exp(-g)));
521	            }
522	        }
523	        barrier();
524	    }
525	}
526	#endif

