  1	#version 450
  2	
  3	#extension GL_EXT_shader_16bit_storage : enable
  4	#extension GL_EXT_shader_explicit_arithmetic_types_float16 : enable
  5	#extension GL_EXT_control_flow_attributes : enable
  6	
  7	// build_hc_combine and the next mixer's grouped RMSNorm, in one dispatch:
  8	// LLM.md P1a's first fusion.
  9	//
 10	//   res[t][c] += out[t] * 2*sigmoid(inject[t][c] / hc)      the combine
 11	//   xn[t][c]   = res[t][c] / rms(res[t][c]) * gamma[c]      the norm
 12	//
 13	// They are two kernels here only because they belong to two mixers. Every
 14	// layer is mix, block, combine, and then the *next* mixer's norm — and the
 15	// combine's output is precisely the norm's input, one stream at a time, with
 16	// no other reader in between. Both are already one workgroup per
 17	// (token, stream), so the fusion needs no new decomposition: a workgroup
 18	// combines its own 2560 values, keeps them in registers, and norms them
 19	// without going back to DRAM.
 20	//
 21	// P1 priced what that is worth. At one token the pair is 3.8 + 6.4 us against
 22	// a 1.0-1.6 us floor for a dispatch that does nothing, and 191 KB of arena
 23	// traffic against 151 fused — so the fusion takes a dispatch out of the step
 24	// **97 times** (the label count is what P1a's gate reads) and one 40 KB read
 25	// of the wide residual with it.
 26	//
 27	// **It is bit-exact against the pair**, which is why the workgroup is 256
 28	// wide and not wider: the norm's sum is a per-thread strided partial and a
 29	// 256-way tree, and both depend on how many threads there are. A wider
 30	// workgroup would be a different sum. The combine is elementwise and carries
 31	// no order at all.
 32	//
 33	// **One workgroup a token, not one a (token, stream)** (P11). The four
 34	// streams of a token combine *the same* block output row — `out[t]` has no
 35	// stream index — so a workgroup per stream read those 2560 floats four times
 36	// where one read serves all four: 110 KB a token becomes 80. This kernel is
 37	// the second largest in a prefill and does no arithmetic at all (10.7% of an
 38	// 8192-row pass, moving 901 MB a dispatch in 7.0 ms — **128 GB/s against the
 39	// 236 a copy gets**), so what it is short of is exactly that. The streams are
 40	// still walked one at a time and each still reduces through the same 256-way
 41	// tree over the same per-thread partials, so every sum is the sum it was and
 42	// the output is bit for bit unchanged.
 43	//
 44	// The two mixers it spans are said by the push block alone — `injOff` and
 45	// `gemmN`/`lowRank` are the *closing* mixer's scatter weights, `gammaOff` the
 46	// *opening* mixer's norm — and the two sets of fields do not overlap, which
 47	// is what let this kernel be added without a 65th push field.
 48	
 49	#include "llm_common.glsl"
 50	
 51	#define CN_LOCAL 256
 52	// Registers per thread: nEmbd / CN_LOCAL, rounded up. 2560 is ten.
 53	#define CN_MAX 10
 54	
 55	layout(local_size_x = CN_LOCAL) in;
 56	
 57	shared float partials[CN_LOCAL];
 58	
 59	void main() {
 60	    uint t = gl_WorkGroupID.x;
 61	    if (t >= pc.tokens) {
 62	        return;
 63	    }
 64	    uint n = pc.nEmbd;
 65	    uint tid = gl_LocalInvocationID.x;
 66	    uint src = pc.outOff + t * n;
 67	
 68	    // The block output, read **once** for all four streams. It is the same
 69	    // row for every one of them, and at ten floats a thread it is ten
 70	    // registers — the whole reason this kernel is a workgroup a token.
 71	    float blk[CN_MAX];
 72	    [[unroll]] for (uint j = 0u; j < CN_MAX; j++) {
 73	        uint i = tid + j * CN_LOCAL;
 74	        blk[j] = (i < n) ? act[src + i] : 0.0;
 75	    }
 76	
 77	    for (uint c = 0u; c < pc.hc; c++) {
 78	        uint dst = pc.resOff + (t * pc.hc + c) * n;
 79	        uint xn = pc.xnOff + t * pc.lda + c * n;
 80	        uint g = pc.gammaOff + c * n;
 81	
 82	        // The inject row stride is the down projection's tile, not hc: the
 83	        // fused [lowRank + hc, wide] weight puts the scatter weights in one
 84	        // 16-wide tile and the kernel stores it whole.
 85	        uint inj = pc.injOff + t * (pc.gemmN - pc.lowRank) + c;
 86	        float w = 2.0 * (1.0 / (1.0 + exp(-act[inj] / float(pc.hc))));
 87	
 88	        // The combined residual, kept in registers so the norm below reads it
 89	        // from there rather than from the arena it was just written to. The
 90	        // indices are compile-time constants, which is what keeps them
 91	        // registers and not scratch.
 92	        //
 93	        // **`precise` is what makes this the same bits as the pair**, and it
 94	        // is not about this kernel's own arithmetic. `llm_hc_combine.comp`
 95	        // writes `act[dst] += act[src] * w` and the backend leaves it a
 96	        // multiply and an add; here the sum has a second reader — the square
 97	        // below — and ACO contracts the pair into a fused multiply-add, which
 98	        // rounds once where the scatter rounds twice. One ulp on 23% of the
 99	        // residual, and every value downstream of it. The SPIR-V of the two
100	        // is identical: this is a backend decision and `precise` is the only
101	        // thing that says no to it.
102	        precise float r[CN_MAX];
103	        float sumSq = 0.0;
104	        [[unroll]] for (uint j = 0u; j < CN_MAX; j++) {
105	            uint i = tid + j * CN_LOCAL;
106	            if (i < n) {
107	                float v = act[dst + i] + blk[j] * w;
108	                act[dst + i] = v;
109	                r[j] = v;
110	                sumSq += v * v;
111	            }
112	        }
113	
114	        // The tree the bit-exactness rests on, one stream at a time. The
115	        // leading barrier is what lets `partials` be reused across the
116	        // streams: the previous stream's tree read it last.
117	        barrier();
118	        partials[tid] = sumSq;
119	        barrier();
120	        for (uint stride = CN_LOCAL / 2u; stride > 0u; stride >>= 1u) {
121	            if (tid < stride) {
122	                partials[tid] += partials[tid + stride];
123	            }
124	            barrier();
125	        }
126	
127	        // 1/sqrt rather than inversesqrt: ggml computes 1.0f/sqrtf(mean + eps)
128	        // and this tensor is compared against its output.
129	        float scale = 1.0 / sqrt(partials[0] / float(n) + uintBitsToFloat(pc.eps));
130	        [[unroll]] for (uint j = 0u; j < CN_MAX; j++) {
131	            uint i = tid + j * CN_LOCAL;
132	            if (i < n) {
133	                hact[xn + i] = float16_t(r[j] * scale * wbuf[g + i]);
134	            }
135	        }
136	    }
137	}

